<script setup>
import { onMounted, onUnmounted, ref } from 'vue'
import userInfoStore from '../stores/user'
import { api } from './api'
import Icon from './Icon.vue'
const emit=defineEmits(['updated','logout','settings']),user=userInfoStore()
const bindings=ref([]),accounts=ref([]),error=ref(''),notice=ref(''),busy=ref(false),qr=ref(null),qrStatus=ref(''),credential=ref(''),importing=ref(''),display=ref(user.displayName),oldPassword=ref(''),newPassword=ref('')
const platforms=[{id:'qqvip',name:'QQ 音乐',mark:'Q'},{id:'netease',name:'网易云音乐',mark:'N'}]
let timer,generation=0,disposed=false
const saved=p=>bindings.value.some(b=>b.provider===p&&b.saved)
const account=p=>accounts.value.find(a=>a.id===p)
async function load(){const [b,a]=await Promise.all([api('/members/me/platforms'),api('/listening/platforms')]);if(!disposed){bindings.value=b;accounts.value=a.accounts||[]}}
async function act(fn){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function cancel(){generation++;clearTimeout(timer);qr.value=null;qrStatus.value=''}
function start(p,type){cancel();const g=generation;act(async()=>{const value=await api('/members/me/platforms/'+p+'/qr',{type});if(disposed||g!==generation)return;qr.value={...value,provider:p};qrStatus.value='请使用手机扫码并确认登录';timer=setTimeout(()=>poll(g),2500)})}
async function poll(g){if(disposed||g!==generation||!qr.value)return;try{const value=await api('/members/me/platforms/'+qr.value.provider+'/qr/'+qr.value.sessionId);if(disposed||g!==generation)return;qrStatus.value=value.status;if(value.done){cancel();await load();emit('updated');notice.value='平台账号已绑定到 '+user.displayName;return}if(value.expired||Date.now()>qr.value.expiresAt){qrStatus.value='二维码已过期，请重新生成';return}}catch(e){if(g!==generation||disposed)return;error.value=e.message;qrStatus.value='检查登录失败，请重新生成二维码';return}timer=setTimeout(()=>poll(g),2500)}
function disconnect(p){act(async()=>{cancel();await api('/members/me/platforms/'+p,undefined,'DELETE');await load();emit('updated')})}
function saveCredential(){act(async()=>{await api('/members/me/platforms/'+importing.value+'/credential',{credential:credential.value},'PUT');credential.value='';importing.value='';await load();emit('updated');notice.value='已保存，请检查平台连接状态。'})}
function profile(){act(async()=>{user.setProfile(await api('/members/me',{displayName:display.value},'PATCH'));notice.value='昵称已保存。'})}
function password(){act(async()=>{await api('/members/me/password',{currentPassword:oldPassword.value,password:newPassword.value},'PUT');oldPassword.value=newPassword.value='';emit('logout')})}
onMounted(()=>load().catch(e=>error.value=e.message));onUnmounted(()=>{disposed=true;cancel();credential.value='';oldPassword.value=newPassword.value=''})
</script>
<template><div class="member-page"><div class="member-identity"><span class="member-avatar large">{{(user.displayName||user.username).slice(0,1).toUpperCase()}}</span><div><h2>{{user.displayName||user.username}}</h2><p>{{user.username}} · {{user.role==='ADMIN'?'管理员，拥有全部管理权限':'家庭成员'}}</p></div><button class="quiet" @click="emit('logout')">退出登录</button></div><p v-if="error" class="inline-error" role="alert">{{error}}</p><p v-if="notice" class="muted" role="status">{{notice}}</p><section class="member-platforms"><div class="section-heading"><div><h2>我的音乐账号</h2><p class="muted">推荐和歌单跟随你的平台账号，播放和下载使用自己的登录信息。</p></div><button class="quiet" :disabled="busy" @click="act(load)">检查连接</button></div><article v-for="p in platforms" :key="p.id" class="member-platform"><span class="platform-letter" :data-platform="p.id">{{p.mark}}</span><div class="member-name"><strong>{{p.name}}</strong><small>{{account(p.id)?'已连接'+(account(p.id).name?' · '+account(p.id).name:''):saved(p.id)?'已保存登录，当前连接未确认':'尚未登录'}}</small></div><div class="member-actions"><button class="quiet" :disabled="busy" @click="start(p.id,'qq')">{{saved(p.id)?'重新扫码':'扫码登录'}}</button><button v-if="p.id==='qqvip'" class="text-button" :disabled="busy" @click="start(p.id,'wechat')">微信登录</button><button v-if="saved(p.id)" class="text-button" :disabled="busy" @click="disconnect(p.id)">断开</button></div></article><div v-if="qr" class="member-qr"><img :src="qr.image" alt="平台登录二维码" /><div><h3>{{platforms.find(p=>p.id===qr.provider)?.name}} 扫码登录</h3><p role="status">{{qrStatus}}</p><button class="quiet" @click="cancel">关闭二维码</button></div></div><details class="member-import"><summary>手动导入自己的登录凭据</summary><form @submit.prevent="saveCredential"><label>平台<select v-model="importing" required><option value="" disabled>选择平台</option><option value="qqvip">QQ 音乐 JSON</option><option value="netease">网易云 Cookie</option></select></label><label>登录凭据<textarea v-model="credential" rows="3" maxlength="65536" autocomplete="off" required /></label><p class="muted">凭据只保存在服务器，不会在页面回显。</p><button class="quiet" :disabled="busy">保存登录</button></form></details></section><section class="member-profile"><form @submit.prevent="profile"><h3>个人资料</h3><label>昵称<input v-model="display" maxlength="40" required /></label><button class="quiet" :disabled="busy">保存昵称</button></form><form v-if="user.role!=='ADMIN'" @submit.prevent="password"><h3>修改登录密码</h3><label>当前密码<input v-model="oldPassword" type="password" autocomplete="current-password" required /></label><label>新密码<input v-model="newPassword" type="password" minlength="8" maxlength="72" autocomplete="new-password" required /></label><button class="quiet" :disabled="busy">修改并重新登录</button></form><div v-else><h3>系统管理</h3><p class="muted">下载目录、音质、自动同步和管理员密码由你统一管理。</p><button class="quiet" @click="emit('settings')">打开系统设置<Icon name="arrow" :size="16" /></button></div></section></div></template>
